class Solution {
    int N;
    vector<int> tree, lazy;

    void pushDown(int node) {
        if (lazy[node] > 0) {
            tree[2 * node] = max(tree[2 * node], lazy[node]);
            lazy[2 * node] = max(lazy[2 * node], lazy[node]);
            tree[2 * node + 1] = max(tree[2 * node + 1], lazy[node]);
            lazy[2 * node + 1] = max(lazy[2 * node + 1], lazy[node]);
            lazy[node] = 0;
        }
    }

    void update(int node, int lo, int hi, int l, int r, int val) {
        if (r <= lo || hi <= l) return;
        if (l <= lo && hi <= r) {
            tree[node] = max(tree[node], val);
            lazy[node] = max(lazy[node], val);
            return;
        }
        pushDown(node);
        int mid = (lo + hi) / 2;
        update(2 * node, lo, mid, l, r, val);
        update(2 * node + 1, mid, hi, l, r, val);
        tree[node] = max(tree[2 * node], tree[2 * node + 1]);
    }

    int query(int node, int lo, int hi, int l, int r) {
        if (r <= lo || hi <= l) return 0;
        if (l <= lo && hi <= r) return tree[node];
        pushDown(node);
        int mid = (lo + hi) / 2;
        return max(query(2 * node, lo, mid, l, r),
                  query(2 * node + 1, mid, hi, l, r));
    }

public:
    vector<int> fallingSquares(vector<vector<int>>& positions) {
        vector<int> coords;
        for (auto& p : positions) {
            coords.push_back(p[0]);
            coords.push_back(p[0] + p[1]);
        }
        sort(coords.begin(), coords.end());
        coords.erase(unique(coords.begin(), coords.end()), coords.end());
        N = (int)coords.size() - 1;
        tree.assign(4 * N + 10, 0);
        lazy.assign(4 * N + 10, 0);

        vector<int> ans;
        ans.reserve(positions.size());
        int globalMax = 0;
        for (auto& p : positions) {
            int l = lower_bound(coords.begin(), coords.end(), p[0]) - coords.begin();
            int r = lower_bound(coords.begin(), coords.end(), p[0] + p[1]) - coords.begin();
            int h = query(1, 0, N, l, r) + p[1];
            update(1, 0, N, l, r, h);
            globalMax = max(globalMax, h);
            ans.push_back(globalMax);
        }
        return ans;
    }
};
